// === NAME - DESCRIPTION: Addition Rule for Union Probability - Compute P(A or B) and recognize overcounting ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Randomize the probabilities
// P(A) and P(B) should be reasonable (between 0.2 and 0.6)
// P(A and B) must be less than or equal to the minimum of P(A) and P(B)
$pA = round(rand(20, 60) / 100, 2);
$pB = round(rand(20, 60) / 100, 2);

// P(A and B) is a fraction of the smaller probability to ensure it's valid
$minP = min($pA, $pB);
$pAandB = round(rand(5, floor($minP * 100 - 1)) / 100, 2);

// Calculate the union: P(A or B) = P(A) + P(B) - P(A and B)
$pAorB = $pA + $pB - $pAandB;

// For the multiple choice part, create distractors
// Distractor 1: Simple sum (overcounts)
$distractorSum = $pA + $pB;
// Distractor 2: Just the intersection
$distractorInt = $pAandB;
// Distractor 3: A random value
$distractorRand = round(rand(10, 90) / 100, 2);

$questions[0] = array(
  "$pAorB", 
  "$distractorSum", 
  "$distractorInt", 
  "$distractorRand"
);
// The correct answer for part (a) is the first one in our array
$answer[0] = 0;

// Part (b) is a conceptual question about overcounting
$questions[1] = array(
  "Adding P(A) and P(B) together counts the outcomes in the intersection twice.",
  "Adding P(A) and P(B) together ignores the outcomes in the intersection.",
  "The Addition Rule only applies if the events are mutually exclusive.",
  "P(A or B) is always equal to the sum of the individual probabilities."
);
$answer[1] = 0;

$anstypes = array("choices", "choices");

// Formatting for display
$pA_disp = sprintf("%.2f", $pA);
$pB_disp = sprintf("%.2f", $pB);
$pAandB_disp = sprintf("%.2f", $pAandB);

$solutionguide = "To find the probability of the union of two events A and B, we use the General Addition Rule: P(A or B) = P(A) + P(B) - P(A and B). Substituting the given values: P(A or B) = $pA_disp + $pB_disp - $pAandB_disp = $pAorB. We subtract the intersection because those outcomes are included in both P(A) and P(B); adding the two probabilities without subtracting the overlap would count those shared outcomes twice.";

// === QUESTION TEXT ===
<p>Suppose we have two events, A and B, with the following probabilities:</p>
<ul>
  <li>`P(A) = $pA_disp`</li>
  <li>`P(B) = $pB_disp`</li>
  <li>`P(A \text{ and } B) = $pAandB_disp`</li>
</ul>

<p>(a) What is the probability that event A <b>or</b> event B occurs? 
`P(A \text{ or } B) =` $answerbox[0]</p>

<p>(b) If you were to simply add `P(A) + P(B)`, why would the result be incorrect?</p>
$answerbox[1]

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
// We generate a set of 4 ordered pairs.
// To make it a function, every x must be unique.
// To make it NOT a function, at least one x must repeat with a different y.

$isFunction = rand(0, 1);

// Generate x values
$x_vals = array();
if ($isFunction) {
    // All x values must be distinct
    $x_vals = diffrands(0, 10, 4);
} else {
    // At least one x value must repeat
    $x_vals = diffrands(0, 10, 3);
    $x_vals[] = $x_vals[rand(0, 2)]; // Duplicate one of the first three
}

// Generate y values
$y_vals = array();
for ($i = 0; $i < 4; $i++) {
    $y_vals[] = rand(0, 15);
}

// If it's NOT a function, we must ensure the repeated x has a DIFFERENT y.
if (!$isFunction) {
    // Find which index was duplicated
    $dup_idx = -1;
    for ($i = 0; $i < 4; $i++) {
        for ($j = $i + 1; $j < 4; $j++) {
            if ($x_vals[$i] == $x_vals[$j]) {
                $dup_idx = $j;
                break 2;
            }
        }
    }
    // Ensure the y value at the duplicate index is different from the original
    // We find the original index first
    $orig_idx = -1;
    for ($i = 0; $i < $dup_idx; $i++) {
        if ($x_vals[$i] == $x_vals[$dup_idx]) {
            $orig_idx = $i;
            break;
        }
    }

    // Force a different y value
    $current_y = $y_vals[$dup_idx];
    $orig_y = $y_vals[$orig_idx];
    while ($current_y == $orig_y) {
        $current_y = rand(0, 15);
    }
    $y_vals[$dup_idx] = $current_y;
}

// Format the set for display
$pairs = array();
for ($i = 0; $i < 4; $i++) {
    $pairs[] = "(" . $x_vals[$i] . ", " . $y_vals[$i] . ")";
}
$set_text = "{" . arraytolist($pairs, ", ") . "}";

// Set the answer
if ($isFunction) {
    $answer = 0; // Yes
} else {
    $answer = 1; // No
}

$questions = array(
    "Yes, it is a function",
    "No, it is not a function"
);

// === QUESTION TEXT ===
Determine if the following relationship is a function:

`$set_text`

$answerbox

// === ANSWER ===
if ($isFunction) {
    $solutionguide = "A relationship is a function if every input (x-value) is paired with exactly one output (y-value). In this set, every x-value is unique, so it is a function.";
} else {
    // Find the duplicate for the solution guide
    $dup_x = -1;
    for ($i = 0; $i < 4; $i++) {
        for ($j = $i + 1; $j < 4; $j++) {
            if ($x_vals[$i] == $x_vals[$j]) {
                $dup_x = $x_vals[$i];
                break 2;
            }
        }
    }
    $solutionguide = "A relationship is a function if every input (x-value) is paired with exactly one output (y-value). In this set, the input `$dup_x` is paired with more than one different output, so it is not a function.";
}

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Ensure pA and pB are distinct and reasonable
$pA = randfrom(array(0.20, 0.25, 0.30, 0.35, 0.40, 0.45));
$pB = randfrom(array(0.20, 0.25, 0.30, 0.35, 0.40, 0.45));

// The overlap must be less than or equal to the smaller of the two
$maxOverlap = min($pA, $pB);
// Ensure pBoth is at least 0.05 and strictly less than the smaller probability to avoid trivial cases
$pBoth = round(rand(0.05, $maxOverlap - 0.01), 2);

// Calculate the union
$pEither = $pA + $pB - $pBoth;

// Part 0: Calculation
$answer[0] = $pEither;

// Part 1: Conceptual Choice
// The previous version had duplicate options in the test report; 
// ensuring unique strings here.
$questions[1] = array(
  "It counts the outcomes in both A and B only once.",
  "It counts the outcomes in both A and B twice.",
  "It ignores the outcomes that are only in A.",
  "It ignores the outcomes that are only in B."
);
$answer[1] = 1; // Index of "It counts the outcomes in both A and B twice."

$anstypes = array("number", "choices");
$strflags[0] = "trim_whitespace";
$strflags[1] = "trim_whitespace";

// Contexts for randomization
$contexts = array(
  array("A student is selected from a class.", "the student is enrolled in Calculus", "the student is enrolled in Physics"),
  array("A professional is selected from a firm.", "the professional has a certification in Project Management", "the professional has a certification in Agile"),
  array("A device is selected from a batch.", "the device has a software glitch", "the device has a hardware glitch"),
  array("A resident is selected from a town.", "the resident owns a dog", "the resident owns a cat")
);
$ctxIdx = rand(0, 3);
$intro = $contexts[$ctxIdx][0];
$eventA = $contexts[$ctxIdx][1];
$eventB = $contexts[$ctxIdx][2];

// === QUESTION TEXT ===
<p>$intro</p>
<p>The probability that `$eventA` is `$pA`.</p>
<p>The probability that `$eventB` is `$pB`.</p>
<p>The probability that both are true is `$pBoth`.</p>

<p>(a) What is the probability that at least one of these is true (the probability of `$eventA` OR `$eventB`)?</p>
<p>Answer: `$answerbox[0]`</p>

<p>(b) Why is simply adding the individual probabilities (`$pA + $pB`) incorrect for finding the probability of the union?</p>
<p>$answerbox[1]</p>

// === ANSWER ===
$solutionguide = 'To find the probability of the union of two events (A or B), we use the Addition Rule: P(A or B) = P(A) + P(B) - P(A and B). 
In this case: ' . $pA . ' + ' . $pB . ' - ' . $pBoth . ' = ' . $pEither . '. 
Simply adding P(A) and P(B) is incorrect because any outcome that belongs to both events is counted twice—once in P(A) and once in P(B). Subtracting the overlap P(A and B) corrects this overcounting.';

// === NAME - DESCRIPTION: Addition Rule for Union Probability - Calculation and Concept ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$pA_pct = rand(20, 50);
$pB_pct = rand(20, 50);
$pBoth_pct = rand(5, min($pA_pct, $pB_pct));

$pA = $pA_pct / 100;
$pB = $pB_pct / 100;
$pBoth = $pBoth_pct / 100;

$answer[0] = $pA + $pB - $pBoth;

$questions[1] = array(
  "Because the students who do both are counted in both the sport group and the instrument group",
  "Because the groups are mutually exclusive",
  "Because the probability of neither is not included",
  "Because the intersection is always zero"
);
$answer[1] = 0;

$anstypes = "number,choices";

// === QUESTION TEXT ===
In a survey of high school students, it was found that ` $pA_pct %` of students play a sport and ` $pB_pct %` of students play a musical instrument. Additionally, ` $pBoth_pct %` of students do both.

<p>Part (a): What is the probability that a randomly selected student plays a sport OR a musical instrument? 
`P(Sport or Instrument) =` $answerbox[0]</p>

<p>Part (b): When calculating the probability of the union (Sport or Instrument), why is it necessary to subtract the probability of the intersection (Sport and Instrument)? 
$answerbox[1]</p>

// === ANSWER ===
$solutionguide = 'To find the probability of the union of two events A and B, we use the General Addition Rule:
`P(A or B) = P(A) + P(B) - P(A and B)`.

In this problem:
`P(Sport) = ' . ($pA_pct/100) . '`
`P(Instrument) = ' . ($pB_pct/100) . '`
`P(Sport and Instrument) = ' . ($pBoth_pct/100) . '`

Step 1: Add the individual probabilities: `' . ($pA_pct/100) . ' + ' . ($pB_pct/100) . ' = ' . (($pA_pct + $pB_pct)/100) . '`.
Step 2: Subtract the overlap (the intersection) to avoid double-counting the students who do both: `' . (($pA_pct + $pB_pct)/100) . ' - ' . ($pBoth_pct/100) . ' = ' . ($answer[0]) . '`.

For part (b), we subtract the intersection because those students are already included in the count for sports and also included in the count for instruments. If we didn\'t subtract them, they would be counted twice.';

