    // Ensure y values are different for the repeated x
    while ($y0[1] == $y0[0]) {
        $y0[1] = rand(1, 100);
    }
}

$pairs = "{( " . $x0[0] . ", " . $y0[0] . " ), ( " . $x0[1] . ", " . $y0[1] . " ), ( " . $x0[2] . ", " . $y0[2] . " ), ( " . $x0[3] . ", " . $y0[3] . " )}";
$questions[0] = array("Yes, it is a function", "No, it is not a function");
$answer[0] = ($isFunc0 == 1) ? 0 : 1;

