$isFunc1 = rand(0, 1);
$x1 = array(rand(1, 10), rand(11, 20), rand(21, 30), rand(31, 40));
$y1 = array(rand(1, 100), rand(1, 100), rand(1, 100), rand(1, 100));

if ($isFunc1 == 0) {
