    $repeatIdx = ($idx == 0) ? 1 : 0;
    $x1[$repeatIdx] = $x1[$idx];
    while ($y1[$repeatIdx] == $y1[$idx]) {
        $y1[$repeatIdx] = rand(1, 100);
    }
}

$questions[1] = array("Yes, it is a function", "No, it is not a function");
$answer[1] = ($isFunc1 == 1) ? 0 : 1;

// Part 2: Graph
$isFunc2 = rand(0, 1);
if ($isFunc2 == 1) {
    // A simple line (Function)
    $svgPath = '<line x1="50" y1="150" x2="150" y2="50" stroke="black" stroke-width="2" />';
} else {
