    $svgPath = '<line x1="100" y1="50" x2="100" y2="150" stroke="black" stroke-width="2" />';
}

$questions[2] = array("Yes, it is a function", "No, it is not a function");
$answer[2] = ($isFunc2 == 1) ? 0 : 1;

// SVG Boilerplate for the graph
$graph = '<svg width="200" height="200" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
    <line x1="10" y1="100" x2="190" y2="100" stroke="gray" stroke-width="1" />
    <line x1="100" y1="10" x2="100" y2="190" stroke="gray" stroke-width="1" />
    <text x="192" y="105" font-size="12">x</text>
    <text x="105" y="15" font-size="12">y</text>
    ' . $svgPath . '
</svg>';

// Solution Guide
$sol0 = ($isFunc0 == 1) ? "Each input x has exactly one output y." : "The input x = " . $x0[0] . " has two different outputs: " . $y0[0] . " and " . $y0[1] . ".";
$sol1 = ($isFunc1 == 1) ? "Each input x in the table has exactly one output y." : "An input x value is repeated with different output y values.";
$sol2 = ($isFunc2 == 1) ? "The graph passes the Vertical Line Test; no vertical line intersects the graph more than once." : "The graph fails the Vertical Line Test; a vertical line intersects the graph at multiple points.";

$solutionguide = "Part (a): $sol0 <br> Part (b): $sol1 <br> Part (c): $sol2";

// === QUESTION TEXT ===
Determine if each of the following relationships is a function.

<p><b>(a)</b> The set of ordered pairs: `$pairs$`
<br>Is this a function? $answerbox[0]</p>

<p><b>(b)</b> The table of values:
<br>
<table border="1" cellpadding="5" style="border-collapse: collapse; text-align: center;">
  <tr><th>x</th><th>y</th></tr>
  <tr><td>`$x1[0]`</td><td>`$y1[0]`</td></tr>
  <tr><td>`$x1[1]`</td><td>`$y1[1]`</td></tr>
  <tr><td>`$x1[2]`</td><td>`$y1[2]`</td></tr>
  <tr><td>`$x1[3]`</td><td>`$y1[3]`</td></tr>
</table>
<br>Is this a function? $answerbox[1]</p>

<p><b>(c)</b> The graph below:
<br>
$graph
<br>Is this a function? $answerbox[2]</p>

// === ANSWER ===
$strflags[0] = "ignore_case,trim_whitespace";
$strflags[1] = "ignore_case,trim_whitespace";
$strflags[2] = "ignore_case,trim_whitespace";

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$cat_names = array("Red", "Blue", "Green", "Yellow");

// Generate counts that sum to a "nice" number for percentage calculation
// Total will be between 40 and 100, and a multiple of 10
$total = (rand(4, 10)) * 10;
$counts = array();
$sum = 0;
for ($i = 0; $i < 3; $i++) {
  $val = rand(5, floor(($total - 15) / 3));
  $counts[$i] = $val;
  $sum += $val;
}
$counts[3] = $total - $sum;

// To shuffle categories and counts together, we use jointshuffle
// jointshuffle requires two arrays of the same length
jointshuffle($cat_names, $counts);

$names = $cat_names;
$vals = $counts;
$percents = array();
for ($i = 0; $i < 4; $i++) {
  $percents[$i] = round(($vals[$i] / $total) * 100, 1);
}

// Part (a): Total group size
$answer[0] = $total;

// Part (b): Percentage for a specific category (pick one at random)
$target_idx = rand(0, 3);
$target_cat = $names[$target_idx];
$target_pct = $percents[$target_idx];
$answer[1] = $target_pct;

// Part (c): Conceptual question about shape
$questions[2] = array(
  "The bars are scaled by different constants, so the relative heights change.",
  "The counts are converted to percentages by dividing each by the same total, so the relative heights remain the same.",
  "Percentages always result in a symmetric distribution regardless of the original counts.",
  "The shape changes because percentages are non-linear transformations of counts."
);
$answer[2] = 1;

$anstypes = "number,number,choices";

// Formatting for the tables
$table_counts = "<table border='1' style='border-collapse: collapse; text-align: center;'>
  <tr><th>Category</th><th>Count</th></tr>";
for ($i = 0; $i < 4; $i++) {
  $table_counts .= "<tr><td>$names[$i]</td><td>$vals[$i]</td></tr>";
}
$table_counts .= "</table>";

$table_percents = "<table border='1' style='border-collapse: collapse; text-align: center;'>
  <tr><th>Category</th><th>Percentage</th></tr>";
for ($i = 0; $i < 4; $i++) {
  $table_percents .= "<tr><td>$names[$i]</td><td>$percents[$i]%</td></tr>";
}
$table_percents .= "</table>";

$vals_list = arraytolist($vals, " + ");
$solutionguide = "Part (a): The total group size is the sum of all counts: " . $vals_list . " = $total. <br>";
$solutionguide .= "Part (b): The percentage for $target_cat is ($vals[$target_idx] / $total) * 100 = $target_pct%. <br>";
$solutionguide .= "Part (c): Since every count is divided by the same total to get the percentage, the ratio between any two bars remains constant, preserving the shape of the graph.";

// === QUESTION TEXT ===
<p>A researcher collected data on the favorite colors of a group of participants. The data is summarized in the two tables below.</p>

<p><strong>Table 1: Counts</strong></p>
$table_counts

<p><strong>Table 2: Percentages</strong></p>
$table_percents

<p>(a) What was the total number of participants in the group? <br>
Answer: $answerbox[0]</p>

<p>(b) Based on the data, what percentage of participants chose $target_cat? <br>
Answer: $answerbox[1]%</p>

<p>(c) If the researcher creates a bar graph for the counts and a bar graph for the percentages, the overall shape of the two graphs will be identical. Why is this the case?</p>
$answerbox[2]

// === NAME - DESCRIPTION: Bar Graph of Counts Versus Percentages - Recover total N, compute percentage, and conceptual check on graph shape ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Randomize the number of categories (3 to 5)
$nCats = rand(3, 5);

// Randomize the total sample size N (between 40 and 100, ensuring it's a multiple of 10 for clean percentages)
$N = rand(4, 10) * 10;

// Generate counts for each category that sum to N
$counts = array();
$sum = 0;
for ($i = 0; $i < $nCats - 1; $i++) {
    // Ensure each category has at least 5 and doesn't exceed N-5*(remaining)
    $min = 5;
    $max = $N - 5 * ($nCats - 1 - $i);
    $val = rand($min, $max);
    $counts[] = $val;
    $sum += $val;
}
$counts[] = $N - $sum;

// Shuffle categories to avoid patterns
// jointshuffle requires two arrays to be shuffled together. 
// We create a dummy array of indices to shuffle the counts.
$indices = array();
for ($i = 0; $i < $nCats; $i++) {
    $indices[] = $i;
}
jointshuffle($counts, $indices);

// Define category names
$catNames = array("Category A", "Category B", "Category C", "Category D", "Category E");
$activeCats = array();
for ($i = 0; $i < $nCats; $i++) {
    $activeCats[] = $catNames[$i];
}

// Calculate percentages for the second table
$percents = array();
for ($i = 0; $i < $nCats; $i++) {
    $cVal = $counts[$i];
    $percents[] = ($cVal / $N) * 100;
}

// Pick a random category for part (b)
$targetIdx = rand(0, $nCats - 1);
$targetCat = $activeCats[$targetIdx];
$targetCount = $counts[$targetIdx];
$targetPerc = $percents[$targetIdx];

// Set answer types: number, number, choices
$anstypes = "number,number,choices";

// Answers
$answer[0] = $N;
$answer[1] = $targetPerc;

// Part (c) choices
$questions[2] = array(
    "The percentages change the relative heights of the bars compared to other graphs, but not to each other.",
    "The total count N is divided out of every bar, so the proportions between the bars remain the same.",
    "Percentages always make the bars shorter, which changes the shape of the distribution.",
    "The shape only stays the same if the total sample size N is 100."
);
$answer[2] = 1; // The second option is correct

// Formatting for the tables
$table1 = "<table border='1' style='border-collapse:collapse; text-align:center;'><tr><th>Category</th><th>Count</th></tr>";
for ($i = 0; $i < $nCats; $i++) {
    $table1 .= "<tr><td>{$activeCats[$i]}</td><td>{$counts[$i]}</td></tr>";
}
$table1 .= "</table>";

$table2 = "<table border='1' style='border-collapse:collapse; text-align:center;'><tr><th>Category</th><th>Percentage</th></tr>";
for ($i = 0; $i < $nCats; $i++) {
    // Display percentages rounded to 1 decimal place
    $table2 .= "<tr><td>{$activeCats[$i]}</td><td>" . round($percents[$i], 1) . "%</td></tr>";
}
$table2 .= "</table>";

$strflags[0] = "trim_whitespace";
$strflags[1] = "trim_whitespace";
$strflags[2] = "ignore_case,trim_whitespace";

// === QUESTION TEXT ===
<p>A researcher collected data on several categories and created two different bar graphs: one showing the counts for each category and one showing the percentages.</p>

<p>The data used for the graphs is summarized in the tables below:</p>

<p><b>Table 1: Counts</b><br>$table1</p>
<p><b>Table 2: Percentages</b><br>$table2</p>

<p>(a) Based on the tables, what was the total sample size `N` used for this study? <br>
`N =` $answerbox[0]</p>

<p>(b) What is the exact percentage for {$targetCat}? (Enter your answer as a number; do not include the percent sign). <br>
Percentage = $answerbox[1]</p>

<p>(c) If the researcher switches from a bar graph of counts to a bar graph of percentages, the overall shape of the graph (the relative heights of the bars) does not change. Why is this?</p>
$answerbox[2]

// === ANSWER ===
$solutionguide = 'Step 1: To find the total sample size `N`, sum the counts from Table 1. ' . $N . ' is the total.
Step 2: To find the percentage for ' . $targetCat . ', divide its count (' . $targetCount . ') by the total `N` (' . $N . ') and multiply by 100: ' . round(($targetCount / $N) * 100, 2) . '%.
Step 3: The shape of a bar graph depends on the ratio between the categories. Since every count is divided by the same constant `N` to get the percentage, the relative proportions remain identical.';

// === NAME - DESCRIPTION: Integrated Math 1 - Determine if the relationship is a function ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
