// Options for all parts
$optYes = "Yes, it is a function";
$optNo = "No, it is not a function";

// --- Part 0: Ordered Pairs ---
$isFunc0 = rand(0, 1);
$x0 = diffrands(1, 15, 4);
$y0 = array(rand(1, 15), rand(1, 15), rand(1, 15), rand(1, 15));
if ($isFunc0 == 0) {
    $repeatIdx0 = rand(0, 2);
    $x0[3] = $x0[$repeatIdx0];
    while ($y0[3] == $y0[$repeatIdx0]) {
        $y0[3] = rand(1, 15);
