// We want a simple 2-variable maximization problem with 2 constraints.
// Max Z = c1*x1 + c2*x2
// s.t.
// a11*x1 + a12*x2 <= b1
// a21*x1 + a22*x2 <= b2

// Randomize coefficients to ensure a positive, non-degenerate solution.
// Candle types: Scented (x1) and Pillar (x2)
// Constraints: Wax (b1) and Labor (b2)

$c1 = randfrom(array(5, 8, 10, 12));
$c2 = randfrom(array(4, 6, 7, 9));

// Ensure a11, a12, a21, a22 are positive and create a non-parallel boundary
$a11 = randfrom(array(2, 3, 4));
$a12 = randfrom(array(1, 2));
$a21 = randfrom(array(1, 2));
$a22 = randfrom(array(3, 4, 5));

// Set b values to ensure the intersection is in the first quadrant and positive
$b1 = randfrom(array(20, 30, 40, 50));
$b2 = randfrom(array(30, 40, 50, 60));

// The initial simplex tableau (augmented)
// Row 0: Z - c1*x1 - c2*x2 = 0
// Row 1: a11*x1 + a12*x2 + s1 = b1
// Row 2: a21*x1 + a22*x2 + s2 = b2
// Tableau size: 3 rows, 5 columns (x1, x2, s1, s2, RHS)

$tab0 = array(-$c1, -$c2, 0, 0, 0);
$tab1 = array($a11, $a12, 1, 0, $b1);
$tab2 = array($a21, $a22, 0, 1, $b2);

$answer[0] = "[($tab0[0],$tab0[1],$tab0[2],$tab0[3],$tab0[4]),($tab1[0],$tab1[1],$tab1[2],$tab1[3],$tab1[4]),($tab2[0],$tab2[1],$tab2[2],$tab2[3],$tab2[4])]";
$answersize[0] = "3,5";

// Solve for the optimal solution
// Intersection of a11*x1 + a12*x2 = b1 and a21*x1 + a22*x2 = b2
$det = $a11 * $a22 - $a12 * $a21;
$x1_opt = ($b1 * $a22 - $b2 * $a12) / $det;
$x2_opt = ($a11 * $b2 - $a21 * $b1) / $det;

// If the intersection is not the max (e.g. one variable is 0), we'd need to check vertices.
// With the chosen ranges, the intersection is typically the optimum.
// Let's check the vertices: (0,0), (b1/a11, 0), (0, b1/a12), (b2/a21, 0), (0, b2/a22), (x1_opt, x2_opt)
$v1_z = 0;
$v2_z = $c1 * ($b1 / $a11);
$v3_z = $c2 * ($b1 / $a12);
$v4_z = $c1 * ($b2 / $a21);
$v5_z = $c2 * ($b2 / $a22);
$v6_z = $c1 * $x1_opt + $c2 * $x2_opt;

// Since we want a clean simplex problem, we ensure x1_opt and x2_opt are positive.
// If not, we regenerate. (In a real MOM question, we'd use a while loop or tighter constraints).
// Given the ranges: a11(2-4), a12(1-2), a21(1-2), a22(3-5), b1(20-50), b2(30-60),
// the intersection is almost always the max and positive.

$max_z = max($v1_z, $v2_z, $v3_z, $v4_z, $v5_z, $v6_z);
$best_x1 = $x1_opt;
$best_x2 = $x2_opt;

// If the intersection was not the max, we'd adjust best_x1/x2.
if ($max_z == $v2_z) { $best_x1 = $b1/$a11; $best_x2 = 0; }
elseif ($max_z == $v3_z) { $best_x1 = 0; $best_x2 = $b1/$a12; }
elseif ($max_z == $v4_z) { $best_x1 = $b2/$a21; $best_x2 = 0; }
elseif ($max_z == $v5_z) { $best_x1 = 0; $best_x2 = $b2/$a22; }

$answer[1] = $best_x1;
$answer[2] = $best_x2;
$answer[3] = $max_z;

