// We need a 3x3 matrix A that is invertible and has a "nice" inverse (integer or simple fraction).
// A reliable way is to start with a known inverse (integer matrix) and invert it to get A.
// Or, create A as a product of elementary matrices.
// Let's use a method where we generate a matrix with a determinant of 1 or -1 to ensure integer inverse.

// Generate a matrix with det = 1 using the property that lower/upper triangular matrices with 1s on diagonal have det=1.
// A = L * U
$l12 = rand(-2, 2); $l21 = rand(-2, 2); $l31 = rand(-2, 2); $l32 = rand(-2, 2);
$u12 = rand(-2, 2); $u13 = rand(-2, 2); $u23 = rand(-2, 2);

// L = [[1, 0, 0], [l21, 1, 0], [l31, l32, 1]]
// U = [[1, u12, u13], [0, 1, u23], [0, 0, 1]]
// A = L * U
$a11 = 1;
$a12 = $u12;
$a13 = $u13;

$a21 = $l21;
$a22 = $l21 * $u12 + 1;
$a23 = $l21 * $u13 + $u23;

$a31 = $l31;
$a32 = $l31 * $u12 + $l32;
$a33 = $l31 * $u13 + $l32 * $u23 + 1;

// Now compute A inverse. Since det(A)=1, A^-1 = adj(A).
// Cofactors C_ij
$c11 = $a22 * $a33 - $a23 * $a32;
$c12 = -($a21 * $a33 - $a23 * $a31);
$c13 = $a21 * $a32 - $a22 * $a31;

$c21 = -($a12 * $a33 - $a13 * $a32);
$c22 = $a11 * $a33 - $a13 * $a31;
$c23 = -($a11 * $a32 - $a12 * $a31);

$c31 = $a12 * $a23 - $a13 * $a22;
$c32 = -($a11 * $a23 - $a13 * $a21);
$c33 = $a11 * $a22 - $a12 * $a21;

// A_inv is the transpose of the cofactor matrix
$inv11 = $c11; $inv12 = $c21; $inv13 = $c31;
$inv21 = $c12; $inv22 = $c22; $inv23 = $c32;
$inv31 = $c13; $inv32 = $c23; $inv33 = $c33;

// Define B as a random integer vector
$b1 = rand(-10, 10);
$b2 = rand(-10, 10);
$b3 = rand(-10, 10);

// Solve X = A^-1 * B
$x1 = $inv11 * $b1 + $inv12 * $b2 + $inv13 * $b3;
$x2 = $inv21 * $b1 + $inv22 * $b2 + $inv23 * $b3;
$x3 = $inv31 * $b1 + $inv32 * $b2 + $inv33 * $b3;

$anstypes = array("calcmatrix", "calcmatrix");

// Part 0: The Inverse Matrix
$answer[0] = "[($inv11,$inv12,$inv13),($inv21,$inv22,$inv23),($inv31,$inv32,$inv33)]";
$answersize[0] = "3,3";
$answerformat[0] = "fraction";

// Part 1: The Solution Vector X
