`AROC = (' . ($L_0 - $k * $b**2) . ' - ' . $ans0 . ') / (' . $b . ' - ' . $a . ')`
`AROC = ' . (($L_0 - $k * $b**2) - $ans0) . ' / ' . ($b - $a) . ' = ' . $ans2 . '` gallons per minute.';

