// === NAME - DESCRIPTION: Matrix Inverse and Equation (3x3) - Find A^{-1} then solve AX=B ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$anstypes = "calcmatrix,calcmatrix";

// Generate a 3x3 matrix A with determinant 1 to ensure integer inverse
// Start with Identity matrix
$a = [
  [1, 0, 0],
  [0, 1, 0],
  [0, 0, 1]
];

// Perform several row operations of the form Ri = Ri + n*Rj to keep det(A) = 1
$multipliers = [-2, -1, 1, 2];
for ($k = 0; $k < 6; $k++) {
  $i = rand(0, 2);
  $j = rand(0, 2);
  if ($i == $j) {
    $k--; // Repeat if same row
    continue;
  }
  $n = randfrom($multipliers);
  for ($col = 0; $col < 3; $col++) {
    $a[$i][$col] = $a[$i][$col] + $n * $a[$j][$col];
  }
}

// Generate a 3x1 matrix B with small integer entries
$b = [
  [rand(-5, 5)],
  [rand(-5, 5)],
  [rand(-5, 5)]
];

// Calculate Determinant (should be 1)
$det = $a[0][0]*($a[1][1]*$a[2][2] - $a[1][2]*$a[2][1]) - $a[0][1]*($a[1][0]*$a[2][2] - $a[1][2]*$a[2][0]) + $a[0][2]*($a[1][0]*$a[2][1] - $a[1][1]*$a[2][0]);

// Calculate Cofactor Matrix C
$c = [];
$c[0][0] = ($a[1][1]*$a[2][2] - $a[1][2]*$a[2][1]);
$c[0][1] = -($a[1][0]*$a[2][2] - $a[1][2]*$a[2][0]);
$c[0][2] = ($a[1][0]*$a[2][1] - $a[1][1]*$a[2][0]);

$c[1][0] = -($a[0][1]*$a[2][2] - $a[0][2]*$a[2][1]);
$c[1][1] = ($a[0][0]*$a[2][2] - $a[0][2]*$a[2][0]);
$c[1][2] = -($a[0][0]*$a[2][1] - $a[0][1]*$a[2][0]);

$c[2][0] = ($a[0][1]*$a[1][2] - $a[0][2]*$a[1][1]);
$c[2][1] = -($a[0][0]*$a[1][2] - $a[0][2]*$a[1][0]);
$c[2][2] = ($a[0][0]*$a[1][1] - $a[0][1]*$a[1][0]);

// Calculate Inverse A^-1 = (1/det) * adj(A)
// adj(A) is the transpose of the cofactor matrix
$inv = [];
for ($r = 0; $r < 3; $r++) {
  $inv[$r] = [];
  for ($col = 0; $col < 3; $col++) {
    $inv[$r][$col] = (float)($c[$col][$r] / $det);
  }
}

// Calculate X = A^-1 * B
$x = [];
for ($r = 0; $r < 3; $r++) {
  $x[$r] = [];
  $sum = 0;
  for ($col = 0; $col < 3; $col++) {
    $sum += $inv[$r][$col] * $b[$col][0];
  }
  $x[$r][0] = (float)$sum;
}

$answer[0] = $inv;
$answer[1] = $x;

