// === COMMON CONTROL ===
// We want to maximize P = Px*x + Py*y
// Subject to:
// wx*x + wy*y <= W
// lx*x + ly*y <= L
// x, y >= 0

// 1. Randomize resource requirements per unit.
$wx = randfrom(array(2, 3, 4));
$wy = randfrom(array(5, 6, 8));
$lx = randfrom(array(4, 5, 6));
$ly = randfrom(array(2, 3, 4));

$r1 = $wx / $wy;
$r2 = $lx / $ly;

// Use a standard while loop instead of do-while to comply with IMathAS restrictions.
// Given the chosen ranges, r1 is always < 1 and r2 is always >= 1, 
// so this loop will typically not execute, but it ensures slope difference.
while (abs($r1 - $r2) < 0.1) {
    $wx = randfrom(array(2, 3, 4));
    $wy = randfrom(array(5, 6, 8));
    $lx = randfrom(array(4, 5, 6));
    $ly = randfrom(array(2, 3, 4));
    $r1 = $wx / $wy;
    $r2 = $lx / $ly;
}

// 2. Randomize the optimal point first to guarantee integer solutions for x and y.
$x_opt = rand(10, 30);
$y_opt = rand(10, 30);

// 3. Calculate the total resources based on the optimal point.
$W = $wx * $x_opt + $wy * $y_opt;
$L = $lx * $x_opt + $ly * $y_opt;

// 4. Randomize profits Px and Py.
$r_min = min($r1, $r2);
$r_max = max($r1, $r2);

// Pick a profit ratio exactly in the middle of the two constraint ratios.
$r_obj = ($r_min + $r_max) / 2;
$Py = randfrom(array(15, 20, 25));
$Px = round($r_obj * $Py, 2);

$maxProfit = round($Px * $x_opt + $Py * $y_opt, 2);

// 5. Define the answers.
