$answer[0] = $wx;
$answer[1] = $wy;
$answer[2] = 1;
$answer[3] = 0;
$answer[4] = $W;

$answer[5] = $lx;
$answer[6] = $ly;
$answer[7] = 0;
$answer[8] = 1;
$answer[9] = $L;

$answer[10] = -$Px;
$answer[11] = -$Py;
$answer[12] = 0;
$answer[13] = 0;
$answer[14] = 0;

$answer[15] = $x_opt;
$answer[16] = $y_opt;
$answer[17] = $maxProfit;

// 18 parts total, all numeric.
